import { ForbiddenException } from '@nestjs/common';
import { validateScope } from './scope.util';

const buildMockDb = (rows: unknown[]) => ({
  select: jest.fn().mockReturnThis(),
  from: jest.fn().mockReturnThis(),
  where: jest.fn().mockReturnThis(),
  limit: jest.fn().mockResolvedValue(rows),
});

describe('validateScope', () => {
  it('resolves without throwing when the scope is present in project_servers.scopes', async () => {
    const db = buildMockDb([
      { scopes: ['read_members', 'check_permissions'] },
    ]);
    await expect(
      validateScope(db as any, 'proj-1', 'server-1', 'read_members'),
    ).resolves.toBeUndefined();
  });

  it('throws ForbiddenException when the scope is missing from project_servers.scopes', async () => {
    const db = buildMockDb([{ scopes: ['read_members'] }]);
    await expect(
      validateScope(db as any, 'proj-1', 'server-1', 'write_webhooks'),
    ).rejects.toThrow(ForbiddenException);
  });

  it('throws ForbiddenException when no project-server mapping exists', async () => {
    const db = buildMockDb([]);
    await expect(
      validateScope(db as any, 'proj-1', 'server-1', 'read_members'),
    ).rejects.toThrow(ForbiddenException);
  });

  it('includes the scope name in the error message', async () => {
    const db = buildMockDb([]);
    await expect(
      validateScope(db as any, 'proj-1', 'server-1', 'manage_bots'),
    ).rejects.toThrow(/manage_bots/);
  });
});

import { ForbiddenException } from '@nestjs/common';
import { eq, and } from 'drizzle-orm';
import { NodePgDatabase } from 'drizzle-orm/node-postgres';
import * as schema from '../../database/entities';

/**
 * Checks whether a project has a specific scope granted for a given server.
 * Scopes are now stored per project-server pair in the project_servers.scopes JSONB column.
 * Throws 403 if the scope is missing.
 */
export async function validateScope(
  db: NodePgDatabase<typeof schema>,
  projectId: string,
  serverId: string,
  requiredScope: string,
): Promise<void> {
  const [row] = await db
    .select({ scopes: schema.projectServers.scopes })
    .from(schema.projectServers)
    .where(
      and(
        eq(schema.projectServers.projectId, projectId),
        eq(schema.projectServers.serverId, serverId),
      ),
    )
    .limit(1);

  if (!row || !Array.isArray(row.scopes) || !row.scopes.includes(requiredScope)) {
    throw new ForbiddenException(
      `Insufficient scope: '${requiredScope}' is required`,
    );
  }
}

import { pgTable, uuid, varchar, primaryKey, jsonb } from 'drizzle-orm/pg-core';
import { projects } from './project.entity';
import { servers } from './server.entity';
import { timestamp } from 'drizzle-orm/pg-core';
import { index } from 'drizzle-orm/pg-core';

export type ProjectServerOperations = {
  READ: boolean;
  SEND_MESSAGES: boolean;
  MANAGE_WEBHOOKS: boolean;
};

export const projectServers = pgTable(
  'project_servers',
  {
    projectId: uuid('project_id')
      .references(() => projects.id)
      .notNull(),
    serverId: varchar('server_id', { length: 255 })
      .references(() => servers.id)
      .notNull(),
    operations: jsonb('operations')
      .$type<ProjectServerOperations>()
      .default({
        READ: true,
        SEND_MESSAGES: false,
        MANAGE_WEBHOOKS: false,
      })
      .notNull(),
    scopes: jsonb('scopes')
      .$type<string[]>()
      .default([])
      .notNull(),
    createdAt: timestamp('created_at').defaultNow().notNull(),
    updatedAt: timestamp('updated_at').defaultNow().notNull(),
  },
  (t) => ({
    pk: primaryKey({ columns: [t.projectId, t.serverId] }),
    projectIdIdx: index('project_servers_project_id_idx').on(t.projectId),
    serverIdIdx: index('project_servers_server_id_idx').on(t.serverId),
  }),
);

