  console.log(`Members: ${insertedMembers.length} total`);
  console.log(
    `  - Member 1: ${insertedMembers[0]?.id} (${insertedMembers[0]?.username}) - Admin role`,
  );
  console.log(
    `  - Member 2: ${insertedMembers[1]?.id} (${insertedMembers[1]?.username}) - Lead role`,
