import { Injectable } from '@nestjs/common';
import { Inject } from '@nestjs/common';
import { DRIZZLE } from './../../database/database.module';
import { NodePgDatabase } from 'drizzle-orm/node-postgres';
import * as schema from './../../database/entities';
import { eq, and, like, or, sql, inArray, lt, exists, SQL } from 'drizzle-orm';
import { members } from '../../database/entities/member.entity';
import { serverMembers } from '../../database/entities/server-member.entity';
import { serverMemberRoles } from '../../database/entities/server-member-role.entity';
import { roles } from '../../database/entities/role.entity';

interface DbPagination {
  offset: number;
  limit: number;
}

interface MemberProfile {
  discordId: string;
  username: string;
  globalName?: string;
  displayName?: string;
  avatar?: string;
  isClubMember: boolean;
  joinedAt?: Date;
  syncedAt: Date;
  roles: Array<{
    id: string;
    name: string;
    color?: number;
    position: number;
  }>;
}

@Injectable()
export class MemberRepository {
  constructor(
    @Inject(DRIZZLE) private readonly db: NodePgDatabase<typeof schema>,
  ) {}

  async findMemberByDiscordId(
    serverId: string,
    discordId: string,
  ): Promise<MemberProfile | null> {
    // Get member with server join info
    const [memberData] = await this.db
      .select({
        member: schema.members,
        joinedAt: schema.serverMembers.joinedAt,
      })
      .from(schema.members)
      .innerJoin(
        schema.serverMembers,
        and(
          eq(schema.members.id, schema.serverMembers.memberId),
          eq(schema.serverMembers.serverId, serverId),
        ),
      )
      .where(eq(schema.members.id, discordId))
      .limit(1);

    if (!memberData) {
      return null;
    }

    // Get roles
    const roles = await this.db
      .select({
        id: schema.roles.id,
        name: schema.roles.name,
        color: schema.roles.color,
        position: schema.roles.position,
      })
      .from(schema.roles)
      .innerJoin(
        schema.serverMemberRoles,
        eq(schema.roles.id, schema.serverMemberRoles.roleId),
      )
      .where(
        and(
          eq(schema.serverMemberRoles.memberId, discordId),
          eq(schema.roles.serverId, serverId),
        ),
      );

    const normalizedRoles = roles.map((r) => ({
      id: r.id,
      name: r.name,
      color: r.color ?? undefined,
      position: r.position ?? 0,
    }));

    return {
      discordId: memberData.member.id,
      username: memberData.member.username,
      globalName: memberData.member.globalName || undefined,
      displayName: memberData.member.displayName || undefined,
      avatar: memberData.member.avatar || undefined,
      isClubMember: memberData.member.isClubMember,
      joinedAt: memberData.joinedAt || undefined,
      syncedAt: memberData.member.syncedAt!,
      roles: normalizedRoles,
    };
  }

  async searchMembers(
    serverId: string,
    query?: string,
    roleId?: string,
    pagination?: DbPagination,
  ): Promise<{
    members: Array<{
      id: string;
      username: string;
      globalName?: string | null;
      displayName?: string | null;
      avatar?: string | null;
      isClubMember: boolean;
      joinedAt?: Date | null;
    }>;
    total: number;
  }> {
    // conditions array for dynamic filters
    const conditions: SQL[] = [];

    // search filter
    if (query?.trim()) {
      const searchTerm = `%${query.trim()}%`;
      conditions.push(
        or(
          like(schema.members.username, searchTerm),
          like(schema.members.globalName, searchTerm),
          like(schema.members.displayName, searchTerm),
        )!
      );
    }

    // role filter
    if (roleId) {
      conditions.push(
        exists(
          this.db
            .select({ id: sql<number>`1` })
            .from(schema.serverMemberRoles)
            .where(
              and(
                eq(schema.serverMemberRoles.roleId, roleId),
                eq(schema.serverMemberRoles.memberId, schema.members.id),
              ),
            ),
        )
      );
    }

    // base query
    let baseQuery = this.db
      .select({
        id: schema.members.id,
        username: schema.members.username,
        globalName: schema.members.globalName,
        displayName: schema.members.displayName,
        avatar: schema.members.avatar,
        isClubMember: schema.members.isClubMember,
        joinedAt: schema.serverMembers.joinedAt,
      })
      .from(schema.members)
      .innerJoin(
        schema.serverMembers,
        and(
          eq(schema.members.id, schema.serverMembers.memberId),
          eq(schema.serverMembers.serverId, serverId),
        ),
      )
      .where(conditions.length > 0 ? and(...conditions) : undefined)
      .$dynamic();

    // total count
    const countResult = await this.db
      .select({ count: sql<number>`count(*)` })
      .from(baseQuery.as('base'))
      .execute();

    const total = parseInt(countResult[0]?.count?.toString() || '0');

    // pagination
    if (pagination) {
      baseQuery = baseQuery
        .limit(pagination.limit)
        .offset(pagination.offset)
        .orderBy(schema.serverMembers.joinedAt);
    }

    const members = await baseQuery.execute();

    return {
      members,
      total,
    };
  }

  // SYNC METHODS

  async upsertMember(
    data: typeof members.$inferInsert,
  ): Promise<typeof members.$inferSelect> {
    const [row] = await this.db
      .insert(members)
      .values({
        ...data,
        updatedAt: new Date(),
      })
      .onConflictDoUpdate({
        target: members.id,
        set: {
          username: data.username,
          globalName: data.globalName,
          displayName: data.displayName,
          avatar: data.avatar,
          email: data.email,
          isClubMember: data.isClubMember,
          syncedAt: data.syncedAt,
          updatedAt: new Date(),
        },
      })
      .returning();
    return row;
  }

  async upsertServerMembership(
    data: typeof serverMembers.$inferInsert,
  ): Promise<typeof serverMembers.$inferSelect> {
    const [row] = await this.db
      .insert(serverMembers)
      .values(data)
      .onConflictDoUpdate({
        target: [serverMembers.serverId, serverMembers.memberId],
        set: {
          joinedAt: data.joinedAt,
          isActive: data.isActive,
          lastSyncedAt: data.lastSyncedAt,
        },
      })
      .returning();
    return row;
  }

  async replaceMemberRoles(
    serverId: string,
    memberId: string,
    roleIds: string[],
  ): Promise<void> {
    await this.db.transaction(async (tx) => {
      const existingRoles = await tx
        .select({ roleId: serverMemberRoles.roleId })
        .from(serverMemberRoles)
        .innerJoin(roles, eq(serverMemberRoles.roleId, roles.id))
        .where(
          and(
            eq(serverMemberRoles.memberId, memberId),
            eq(roles.serverId, serverId),
          ),
        );

      if (existingRoles.length > 0) {
        const roleIdsToDelete = existingRoles.map((r) => r.roleId);
        await tx
          .delete(serverMemberRoles)
          .where(
            and(
              eq(serverMemberRoles.memberId, memberId),
              inArray(serverMemberRoles.roleId, roleIdsToDelete),
            ),
          );
      }

      if (roleIds.length > 0) {
        await tx.insert(serverMemberRoles).values(
          roleIds.map((roleId) => ({
            memberId,
            roleId,
          })),
        );
      }
    });
  }

  async markInactiveForServer(
    serverId: string,
    syncStart: Date,
  ): Promise<number> {
    const result = await this.db
      .update(serverMembers)
      .set({ isActive: false, lastSyncedAt: new Date() })
      .where(
        and(
          eq(serverMembers.serverId, serverId),
          eq(serverMembers.isActive, true),
          lt(serverMembers.lastSyncedAt, syncStart),
        ),
      );
    return result.rowCount ?? 0;
  }

  // role deletion
  async deleteMemberRolesByRoleId(roleId: string): Promise<void> {
    await this.db
      .delete(serverMemberRoles)
      .where(eq(serverMemberRoles.roleId, roleId));
  }
}

import { Body, Controller, Get, HttpCode, HttpStatus, Param, Post, UseGuards } from '@nestjs/common';
import {
  ApiBody,
  ApiBearerAuth,
  ApiForbiddenResponse,
  ApiOkResponse,
  ApiOperation,
  ApiParam,
  ApiSecurity,
  ApiTags,
  ApiUnauthorizedResponse,
} from '@nestjs/swagger';
import { CheckPermissionDto } from './dto/check-permission.dto';
import {
  CheckPermissionsBatchDto,
  CheckMode,
} from './dto/check-permissions-batch.dto';
import { UpsertInheritanceRuleDto } from './dto/upsert-inheritance-rule.dto';
import { PermissionsService } from './permissions.service';
import { SystemAdminGuard } from '../../common/guards/system-admin.guard';
import { ApiKeyGuard } from '../../common/guards/api-key.guard';

@ApiTags('Permissions')
@Controller('permissions')
export class PermissionsController {
  constructor(private readonly permissionsService: PermissionsService) {}

  // ─── Permission Checking API (project-scoped) ──────────────────────

  @Post('check')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ApiKeyGuard)
  @ApiSecurity('api-key')
  @ApiOperation({
    summary: 'Check a single permission',
    description:
      'Resolves whether a Discord member holds a specific permission in a given server. ' +
      'Permissions are derived from their roles and any configured inheritance rules.',
  })
  @ApiBody({ type: CheckPermissionDto })
  @ApiOkResponse({ description: 'Permission check result returned.' })
  @ApiUnauthorizedResponse({ description: 'Valid API key required.' })
  checkPermission(@Body() dto: CheckPermissionDto) {
    return this.permissionsService.checkPermission(dto);
  }

  @Post('check-batch')
  @HttpCode(HttpStatus.OK)
  @UseGuards(ApiKeyGuard)
  @ApiSecurity('api-key')
  @ApiOperation({
    summary: 'Check multiple permissions (batch)',
    description:
      'Checks a list of permissions for a member in one call. ' +
      'Set `mode` to `ALL` to require every permission, or `ANY` to pass if at least one matches.',
  })
  @ApiBody({ type: CheckPermissionsBatchDto })
  @ApiOkResponse({ description: 'Batch permission check result returned.' })
  @ApiUnauthorizedResponse({ description: 'Valid API key required.' })
  async checkPermissionBatch(@Body() dto: CheckPermissionsBatchDto) {
    if (dto.mode === CheckMode.ALL) {
      return this.permissionsService.hasAllPermissions(
        dto.serverId,
        dto.discordId,
        dto.permissions,
      );
    }

    return this.permissionsService.hasAnyPermission(
      dto.serverId,
      dto.discordId,
      dto.permissions,
    );
  }

  @Get(':serverId/:discordId')
  @UseGuards(ApiKeyGuard)
  @ApiSecurity('api-key')
  @ApiOperation({
    summary: 'Get full resolved permissions for a member',
    description:
      'Returns every effective permission the member holds in the server, ' +
      'including permissions inherited via role hierarchy rules. ' +
      'Requires the `check_permissions` scope for this server.',
  })
  @ApiParam({ name: 'serverId', description: 'Discord guild snowflake ID', example: '123456789012345678' })
  @ApiParam({ name: 'discordId', description: 'Discord user snowflake ID', example: '876543210987654321' })
  @ApiOkResponse({ description: 'Full permission set returned.' })
  @ApiUnauthorizedResponse({ description: 'Valid API key required.' })
  getMemberPermissions(
    @Param('serverId') serverId: string,
    @Param('discordId') discordId: string,
  ) {
    return this.permissionsService.getMemberPermissions(serverId, discordId);
  }

  // ─── Admin-only endpoints ──────────────────────────────────────────

  @Post('inheritance-rules')
  @HttpCode(HttpStatus.OK)
  @UseGuards(SystemAdminGuard)
  @ApiBearerAuth('session-token')
  @ApiOperation({
    summary: 'Create or update an inheritance rule',
    description:
      'Upserts a permission inheritance rule that causes members holding a source role to ' +
      'also receive all permissions of a target role, optionally scoped to a specific server.',
  })
  @ApiBody({ type: UpsertInheritanceRuleDto })
  @ApiOkResponse({ description: 'Inheritance rule upsert result returned.' })
  @ApiUnauthorizedResponse({ description: 'Authentication required.' })
  @ApiForbiddenResponse({ description: 'System Admin access required.' })
  upsertInheritanceRule(@Body() dto: UpsertInheritanceRuleDto) {
    return this.permissionsService.upsertInheritanceRule(dto);
  }

  @Get('inheritance-rules')
  @UseGuards(SystemAdminGuard)
  @ApiBearerAuth('session-token')
  @ApiOperation({
    summary: 'List inheritance rules',
    description: 'Returns all configured role inheritance rules.',
  })
  @ApiOkResponse({ description: 'Inheritance rules list returned.' })
  @ApiUnauthorizedResponse({ description: 'Authentication required.' })
  @ApiForbiddenResponse({ description: 'System Admin access required.' })
  listInheritanceRules() {
    return this.permissionsService.listInheritanceRules();
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { and, desc, eq } from 'drizzle-orm';
import { NodePgDatabase } from 'drizzle-orm/node-postgres';
import { DRIZZLE } from '../../database/database.module';
import * as schema from '../../database/entities';
import {
  projectServerAccessAudit,
  projectServers,
  projects,
  servers,
} from '../../database/entities';
import type { ProjectServerOperations } from '../../database/entities/project-server.entity';
import { verifyApiKey } from '../../common/utils/api-key.util';

// ─── Project-Server Access Types ──────────────────────────────────────────

export const PROJECT_SERVER_OPERATION_VALUES = [
  'READ',
  'SEND_MESSAGES',
  'MANAGE_WEBHOOKS',
] as const;

export type ProjectServerOperation =
  (typeof PROJECT_SERVER_OPERATION_VALUES)[number];

export const DEFAULT_PROJECT_SERVER_OPERATIONS: ProjectServerOperations = {
  READ: true,
  SEND_MESSAGES: false,
  MANAGE_WEBHOOKS: false,
};

export const isProjectServerOperation = (
  value: string,
): value is ProjectServerOperation =>
  (PROJECT_SERVER_OPERATION_VALUES as readonly string[]).includes(value);

type AccessAuditAction = 'GRANT' | 'UPDATE' | 'REVOKE';

export interface ProjectRow {
  id: string;
  name: string;
  description: string | null;
  apiKeyPrefix: string | null;
  apiKeyCreatedAt: Date;
  apiKeyLastUsedAt: Date | null;
  isActive: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export interface CreateProjectData {
  name: string;
  description?: string;
  apiKeyHash: string;
  apiKeyPrefix: string;
}

export interface UpdateProjectData {
  name?: string;
  description?: string;
}

@Injectable()
export class ProjectsRepository {
  constructor(
    @Inject(DRIZZLE)
    private readonly db: NodePgDatabase<typeof schema>,
  ) {}

  async create(data: CreateProjectData): Promise<ProjectRow> {
    const [project] = await this.db
      .insert(schema.projects)
      .values({
        name: data.name,
        description: data.description,
        apiKeyHash: data.apiKeyHash,
        apiKeyPrefix: data.apiKeyPrefix,
        isActive: true,
      })
      .returning();

    return this.toProjectRow(project);
  }

  async findAll(): Promise<ProjectRow[]> {
    const projects = await this.db
      .select({
        id: schema.projects.id,
        name: schema.projects.name,
        description: schema.projects.description,
        apiKeyPrefix: schema.projects.apiKeyPrefix,
        apiKeyCreatedAt: schema.projects.apiKeyCreatedAt,
        apiKeyLastUsedAt: schema.projects.apiKeyLastUsedAt,
        isActive: schema.projects.isActive,
        createdAt: schema.projects.createdAt,
        updatedAt: schema.projects.updatedAt,
      })
      .from(schema.projects);

    return projects.map((p) => ({ ...p }));
  }

  async findOne(id: string): Promise<ProjectRow | null> {
    const [project] = await this.db
      .select({
        id: schema.projects.id,
        name: schema.projects.name,
        description: schema.projects.description,
        apiKeyPrefix: schema.projects.apiKeyPrefix,
        apiKeyCreatedAt: schema.projects.apiKeyCreatedAt,
        apiKeyLastUsedAt: schema.projects.apiKeyLastUsedAt,
        isActive: schema.projects.isActive,
        createdAt: schema.projects.createdAt,
        updatedAt: schema.projects.updatedAt,
      })
      .from(schema.projects)
      .where(eq(schema.projects.id, id))
      .limit(1);

    if (!project) return null;

    return { ...project };
  }

  async update(
    id: string,
    data: UpdateProjectData,
  ): Promise<ProjectRow | null> {
    const [project] = await this.db
      .update(schema.projects)
      .set({ ...data, updatedAt: new Date() })
      .where(eq(schema.projects.id, id))
      .returning({
        id: schema.projects.id,
        name: schema.projects.name,
        description: schema.projects.description,
        apiKeyPrefix: schema.projects.apiKeyPrefix,
        apiKeyCreatedAt: schema.projects.apiKeyCreatedAt,
        apiKeyLastUsedAt: schema.projects.apiKeyLastUsedAt,
        isActive: schema.projects.isActive,
        createdAt: schema.projects.createdAt,
        updatedAt: schema.projects.updatedAt,
      });

    if (!project) return null;

    return { ...project };
  }

  async updateKey(
    id: string,
    apiKeyHash: string,
    apiKeyPrefix: string,
  ): Promise<void> {
    await this.db
      .update(schema.projects)
      .set({
        apiKeyHash,
        apiKeyPrefix,
        apiKeyCreatedAt: new Date(),
        updatedAt: new Date(),
      })
      .where(eq(schema.projects.id, id));
  }

  async setActive(id: string, isActive: boolean): Promise<void> {
    await this.db
      .update(schema.projects)
      .set({ isActive, updatedAt: new Date() })
      .where(eq(schema.projects.id, id));
  }

  // ─────────────────────────────── Delete ───────────────────────────────

  async delete(id: string): Promise<boolean> {
    // Clear dependent rows first to avoid FK violations
    await this.db
      .delete(projectServerAccessAudit)
      .where(eq(projectServerAccessAudit.projectId, id));
    await this.db
      .delete(projectServers)
      .where(eq(projectServers.projectId, id));

    const result = await this.db
      .delete(schema.projects)
      .where(eq(schema.projects.id, id))
      .returning({ id: schema.projects.id });

    return result.length > 0;
  }

  // ─────────────────────────────── Helpers ──────────────────────────────

  private toProjectRow(
    project: typeof schema.projects.$inferSelect,
  ): ProjectRow {
    return {
      id: project.id,
      name: project.name,
      description: project.description,
      apiKeyPrefix: project.apiKeyPrefix,
      apiKeyCreatedAt: project.apiKeyCreatedAt,
      apiKeyLastUsedAt: project.apiKeyLastUsedAt,
      isActive: project.isActive,
      createdAt: project.createdAt,
      updatedAt: project.updatedAt,
    };
  }

  // ─────────────────────── Auth-support queries ──────────────────────────

  /** Validate redirect URI against the project's allowed URI list */
  async isRedirectUriAllowed(
    projectId: string,
    redirectUri: string,
  ): Promise<boolean> {
    const rows = await this.db
      .select({ redirectUri: schema.projects.redirectUri })
      .from(schema.projects)
      .where(eq(schema.projects.id, projectId))
      .limit(1);

    if (!rows[0]?.redirectUri) return false;

    // Support comma-separated list of allowed URIs
    const allowedUris = rows[0].redirectUri.split(',').map((u) => u.trim());
    return allowedUris.includes(redirectUri);
  }

  /** Get the role IDs that are allowed to access a project */
  async findAllowedRoleIds(projectId: string): Promise<string[]> {
    const rows = await this.db
      .select({ roleId: schema.projectRoles.roleId })
      .from(schema.projectRoles)
      .where(eq(schema.projectRoles.projectId, projectId));

    return rows.map((r) => r.roleId);
  }

  /** Get the allowed roles with full role details */
  async findAllowedRoles(projectId: string) {
    return this.db
      .select({
        roleId: schema.projectRoles.roleId,
        roleName: schema.roles.name,
        roleColor: schema.roles.color,
        rolePosition: schema.roles.position,
      })
      .from(schema.projectRoles)
      .innerJoin(schema.roles, eq(schema.projectRoles.roleId, schema.roles.id))
      .where(eq(schema.projectRoles.projectId, projectId));
  }

  /** Find a project by its raw API key (prefix.secret format) */
  async findByApiKey(apiKey: string) {
    const dotIndex = apiKey.indexOf('.');
    if (dotIndex === -1) return null;
    const prefix = apiKey.substring(0, dotIndex);
    const secret = apiKey.substring(dotIndex + 1);
    if (!prefix || !secret) return null;

    const results = await this.db
      .select()
      .from(schema.projects)
      .where(
        and(
          eq(schema.projects.apiKeyPrefix, prefix),
          eq(schema.projects.isActive, true),
        ),
      )
      .limit(1);

    const project = results[0] || null;
    if (!project || !project.apiKeyHash) return null;
    return verifyApiKey(secret, project.apiKeyHash) ? project : null;
  }

  /** Update the allowed redirect URI(s) for a project */
  async updateRedirectUri(projectId: string, redirectUri: string) {
    const rows = await this.db
      .update(schema.projects)
      .set({ redirectUri, updatedAt: new Date() })
      .where(eq(schema.projects.id, projectId))
      .returning();
    return rows[0] || null;
  }

  /** Regenerate a project's API key, returning the updated project or null */
  async regenerateApiKey(
    projectId: string,
    newHash: string,
    newPrefix: string,
  ) {
    const rows = await this.db
      .update(schema.projects)
      .set({
        apiKeyHash: newHash,
        apiKeyPrefix: newPrefix,
        apiKeyCreatedAt: new Date(),
        updatedAt: new Date(),
      })
      .where(eq(schema.projects.id, projectId))
      .returning();

    return rows[0] || null;
  }

  // ─── Project-Server Access ────────────────────────────────────────────

  async findProjectById(projectId: string) {
    const [row] = await this.db
      .select({ id: projects.id, name: projects.name })
      .from(projects)
      .where(eq(projects.id, projectId))
      .limit(1);

    return row ?? null;
  }

  async findServerById(serverId: string) {
    const [row] = await this.db
      .select({
        id: servers.id,
        name: servers.name,
        isActive: servers.isActive,
      })
      .from(servers)
      .where(eq(servers.id, serverId))
      .limit(1);

    return row ?? null;
  }

  async findMainServers() {
    return this.db
      .select({ id: servers.id, name: servers.name })
      .from(servers)
      .where(
        and(
          eq(servers.isMain, true),
          eq(servers.isActive, true),
        ),
      );
  }

  async findAccessMapping(projectId: string, serverId: string) {
    const [row] = await this.db
      .select()
      .from(projectServers)
      .where(
        and(
          eq(projectServers.projectId, projectId),
          eq(projectServers.serverId, serverId),
        ),
      )
      .limit(1);

    return row ?? null;
  }

  async upsertAccessMapping(
    projectId: string,
    serverId: string,
    operations: ProjectServerOperations,
    now: Date,
    scopes: string[] = [],
  ) {
    const [row] = await this.db
      .insert(projectServers)
      .values({
        projectId,
        serverId,
        operations,
        scopes,
        createdAt: now,
        updatedAt: now,
      })
      .onConflictDoUpdate({
        target: [projectServers.projectId, projectServers.serverId],
        set: {
          operations,
          scopes,
          updatedAt: now,
        },
      })
      .returning();

    return row;
  }

  async revokeAccessMapping(projectId: string, serverId: string) {
    const [row] = await this.db
      .delete(projectServers)
      .where(
        and(
          eq(projectServers.projectId, projectId),
          eq(projectServers.serverId, serverId),
        ),
      )
      .returning();

    return row ?? null;
  }

  async insertAuditEntry(params: {
    projectId: string;
    serverId: string;
    action: AccessAuditAction;
    operationsBefore: ProjectServerOperations | null;
    operationsAfter: ProjectServerOperations | null;
    changedBy: string;
    changedAt: Date;
  }) {
    await this.db.insert(projectServerAccessAudit).values({
      projectId: params.projectId,
      serverId: params.serverId,
      action: params.action,
      operationsBefore: params.operationsBefore,
      operationsAfter: params.operationsAfter,
      changedBy: params.changedBy,
      changedAt: params.changedAt,
    });
  }

  async isOperationAllowed(
    projectId: string,
    serverId: string,
    operation: ProjectServerOperation,
  ): Promise<boolean> {
    const access = await this.findAccessMapping(projectId, serverId);
    if (!access) return false;

    const operations = access.operations;
    return Boolean(operations?.[operation]);
  }

  async listServersByProject(projectId: string) {
    return this.db
      .select({
        projectId: projectServers.projectId,
        serverId: servers.id,
        serverName: servers.name,
        operations: projectServers.operations,
        scopes: projectServers.scopes,
        updatedAt: projectServers.updatedAt,
      })
      .from(projectServers)
      .innerJoin(servers, eq(servers.id, projectServers.serverId))
      .where(eq(projectServers.projectId, projectId))
      .orderBy(servers.name);
  }

  async listProjectsByServer(serverId: string) {
    return this.db
      .select({
        serverId: projectServers.serverId,
        projectId: projects.id,
        projectName: projects.name,
        operations: projectServers.operations,
        scopes: projectServers.scopes,
        updatedAt: projectServers.updatedAt,
      })
      .from(projectServers)
      .innerJoin(projects, eq(projects.id, projectServers.projectId))
      .where(eq(projectServers.serverId, serverId))
      .orderBy(projects.name);
  }

  async listAccessMatrix() {
    return this.db
      .select({
        projectId: projects.id,
        projectName: projects.name,
        serverId: servers.id,
        serverName: servers.name,
        operations: projectServers.operations,
        scopes: projectServers.scopes,
        updatedAt: projectServers.updatedAt,
      })
      .from(projectServers)
      .innerJoin(projects, eq(projects.id, projectServers.projectId))
      .innerJoin(servers, eq(servers.id, projectServers.serverId))
      .orderBy(projects.name, servers.name);
  }

  async listAudit(limit = 100) {
    const safeLimit = Math.max(limit, 1);
    return this.db
      .select()
      .from(projectServerAccessAudit)
      .orderBy(desc(projectServerAccessAudit.changedAt))
      .limit(safeLimit);
  }

  /** Return true if a project has been granted access to the given server */
  async hasServerAccess(projectId: string, serverId: string): Promise<boolean> {
    const row = await this.findAccessMapping(projectId, serverId);
    return row !== null;
  }

  /** Check whether a project-server mapping includes a specific scope */
  async isScopeAllowed(
    projectId: string,
    serverId: string,
    scope: string,
  ): Promise<boolean> {
    const access = await this.findAccessMapping(projectId, serverId);
    if (!access) return false;
    return Array.isArray(access.scopes) && access.scopes.includes(scope);
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Patch,
  Post,
  UseGuards,
} from '@nestjs/common';
import {
  ApiBearerAuth,
  ApiBody,
  ApiCreatedResponse,
  ApiForbiddenResponse,
  ApiNoContentResponse,
  ApiNotFoundResponse,
  ApiOkResponse,
  ApiOperation,
  ApiParam,
  ApiTags,
  ApiUnauthorizedResponse,
} from '@nestjs/swagger';
import { ServersService } from './servers.service';
import { CreateServerDto } from './dto/create-server.dto';
import { UpdateServerDto } from './dto/update-server.dto';
import { SystemAdminGuard } from '../../common/guards/system-admin.guard';
import { DisableServerDto } from './dto/disable-server.dto';

